"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[102],{9102:(e,t,i)=>{i.r(t),i.d(t,{PAPERS:()=>a});let a=[{id:"2610.17665",title:"RoTA-Bench: Evaluating 3D Spatial Reasoning through Interactive Projection Alignment",up:187,href:"https://arxiv.org/abs/2610.17665",abstract:"Can vision-language models turn 2D observations into 3D understanding that supports precise action? This requires inferring object geometry, anticipating the effects of rotation, and refining actions through visual feedback. We introduce RoTA-Bench to evaluate these abilities through interactive 3D-to-2D projection alignment. Given a target silhouette, a model observes a rotated object and chooses successive rotations to recover the target projection within a limited action budget. Our automated pipeline constructs silhouette-preserving 3D objects from 2D icons and uses reversible initializati",pdfUrl:"https://arxiv.org/pdf/2610.17665",primaryCategory:"cs.AI",published:"2026-10-14T00:00:00Z"},{id:"2610.18813",title:"Self-Evolving Agent Harness",up:183,href:"https://arxiv.org/abs/2610.18813",abstract:"Harness self-evolution revises an agent's software scaffolding, including prompts, memory, workflows, and executable components, while keeping model weights fixed. We formalize a feedback-driven process in which accepted revisions persist across runs. The framework separates update targets from proposal and admission mechanisms. It distinguishes changes to interpreted state from revisions to tools and code, repository-level control logic, and plugin composition. We characterize search through evolutionary optimization and examine its reliability through continual PAC-learning. Under explicit a",pdfUrl:"https://arxiv.org/pdf/2610.18813",primaryCategory:"cs.AI",published:"2026-10-13T00:00:00Z"},{id:"2610.21601",title:"Waypoint-OPD: Transferring RL-Induced Policy Shifts via Gated On-Policy Distillation",up:181,href:"https://arxiv.org/abs/2610.21601",abstract:"Policy-shift distillation reuses the difference between a teacher's log probabilities before and after reinforcement learning (RL) as supervision on student-generated trajectories. However, this endpoint policy shift cannot reveal whether local action preferences evolved consistently during teacher training. The same endpoint shift can result from early and late shifts that reinforce or partially cancel each other. We investigate whether agreement between early and late teacher policy shifts can guide selective transfer. We introduce Waypoint-guided On-Policy Distillation (Waypoint-OPD), which",pdfUrl:"https://arxiv.org/pdf/2610.21601",primaryCategory:"cs.LG",published:"2026-10-15T00:00:00Z"},{id:"2610.14993",title:"Learning Where to Split: Dynamic Band Splitting for Audio Source Separation",up:130,href:"https://arxiv.org/abs/2610.14993",abstract:"Audio source separation models must preserve fine spectral structure while keeping the cost of the separator tractable. Band-split architectures reduce this cost by manually partitioning the spectrum into predefined frequency bands and encoding each band as a token, but the same boundaries are used for every mixture. Because informative spectral structure varies with source content, fixed boundaries can merge discriminative components or spend tokens where little resolution is needed. We introduce Dynamic Band Splitting (DBS), an end-to-end framework that adapts boundary locations and band wid",pdfUrl:"https://arxiv.org/pdf/2610.14993",primaryCategory:"cs.SD",published:"2026-10-10T00:00:00Z"},{id:"2610.22276",title:"MJev-Spatial: System One Spatial Intelligence via Native Attention Matching",up:117,href:"https://arxiv.org/abs/2610.22276",abstract:"Spatial intelligence lets an agent perceive and act in the physical world, and many of its judgments must be made at interaction rates: which spatial relation holds, how far an object is, or where to place it. Vision-language models (VLMs) produce these answers by free-form text generation, paying for autoregressive decoding and answer parsing even though the output space is compact: one of a few options, a scalar, or a 2D point. In light of this, we introduce MJev-Spatial, a System 1 multimodal decision model that tackles all three types of spatial understanding tasks within a unified classif",pdfUrl:"https://arxiv.org/pdf/2610.22276",primaryCategory:"cs.CV",published:"2026-10-15T00:00:00Z"},{id:"2610.20341",title:"InfiniSplat v2: Analyzing and Improving Feed-Forward 3DGS from Any Views",up:114,href:"https://arxiv.org/abs/2610.20341",abstract:"Feed-forward Gaussian reconstruction builds 3D scenes directly from input images for novel view rendering, but learning Gaussian attributes from predicted geometry for high-quality rendering under large viewpoint changes remains challenging. We analyze limitations in Gaussian attribute learning and introduce InfiniSplat v2, which improves rendering quality through architectural and training changes. Our method decouples geometry and attribute prediction with a frozen geometry branch, aligns predicted Gaussians using ground-truth camera poses during training, and adopts large-angle target view ",pdfUrl:"https://arxiv.org/pdf/2610.20341",primaryCategory:"cs.CV",published:"2026-10-14T00:00:00Z"},{id:"2610.22350",title:"FDE-Gym: The Last Mile of AI Delivery",up:113,href:"https://arxiv.org/abs/2610.22350",abstract:"Existing agent benchmarks typically evaluate agents on well-specified tasks defined by issue reports, specifications, or task tickets. Real-world customer delivery is different: forward-deployed engineers (FDEs) must clarify ambiguous requirements, work in live systems, and uncover unstated constraints. We introduce FDE-Gym, a benchmark of 95 end-to-end delivery tasks from 20 customer scenarios across 18 sectors, each adapted by industry experts from real-world delivery projects. In simulated customer environments with scripted stakeholders and modifiable customer systems, agents interact with",pdfUrl:"https://arxiv.org/pdf/2610.22350",primaryCategory:"cs.AI",published:"2026-10-15T00:00:00Z"},{id:"2610.22200",title:"OpenGCUA: Toward a Fully Open Stack for Generalist Computer Use",up:104,href:"https://arxiv.org/abs/2610.22200",abstract:"Computer use has reached a turning point: the focus is expanding from GUI-only interaction to systems that complete tasks on users' computers through visual and programmatic interfaces. We define a generalist computer-use agent (GCUA) as a system in which the model chooses how to observe, act, and organize its work across visual and programmatic interfaces. Yet frontier implementations, such as GPT-6 Astra's computer-use system, remain largely closed, limiting systematic study of their design. We introduce Open Generalist CUA (OpenGCUA), an ongoing project to develop and open the full stack fo",pdfUrl:"https://arxiv.org/pdf/2610.22200",primaryCategory:"cs.CV",published:"2026-10-15T00:00:00Z"},{id:"2610.20939",title:"MAI-Gym: An Open All-in-One Platform for GUI Agent Evaluation and RL Training across Mobile and Computer Environments",up:59,href:"https://arxiv.org/abs/2610.20939",abstract:"Online reinforcement learning (RL) with verifiable rewards has driven rapid progress in mathematics, coding, and tool use, but scaling this success to GUI agents remains challenging due to the high cost of interactive environments and the scarcity of realistic training tasks. We introduce MAI-Gym, an open all-in-one platform that unifies GUI agent evaluation, data collection, and online RL training across mobile, computer, and web environments. Through a shared rollout pipeline, MAI-Gym ensures consistent agent behavior across evaluation and training, supports ten established benchmarks, and s",pdfUrl:"https://arxiv.org/pdf/2610.20939",primaryCategory:"cs.AI",published:"2026-10-14T00:00:00Z"},{id:"2610.22174",title:"Mosaic: Multi-Session Agentic Reinforcement Learning",up:46,href:"https://arxiv.org/abs/2610.22174",abstract:"Most existing agentic reinforcement learning methods assume single-session trajectories, where interaction proceeds within one continuously accumulated context. However, agentic techniques such as context compaction and subagent forking may produce trajectories spanning multiple sessions, creating a mismatch between the single-session training assumption and inference-time execution. Therefore, we introduce Multi-Session Agentic Reinforcement Learning, a more general setting that supports an arbitrary number of sessions within a trajectory. Under this setting, a widely adopted method is to bro",pdfUrl:"https://arxiv.org/pdf/2610.22174",primaryCategory:"cs.CL",published:"2026-10-15T00:00:00Z"},{id:"2610.19849",title:"DeltaStreamer: Towards Human-Like Agentic Streaming Video Understanding",up:34,href:"https://arxiv.org/abs/2610.19849",abstract:"We propose DeltaStreamer, a novel agentic framework for streaming video understanding inspired by how humans observe, remember, and investigate. Streaming video understanding requires a system to retain evidence before knowing which details future queries will need. Existing approaches often obscure event transitions and omit relevant details when compressing video history, and cannot recover missing visual evidence. DeltaStreamer addresses these limitations by combining change-aware memory with query-driven planning and targeted evidence gathering with replay. Before a query arrives, it conti",pdfUrl:"https://arxiv.org/pdf/2610.19849",primaryCategory:"cs.CV",published:"2026-10-14T00:00:00Z"},{id:"2610.21306",title:"VLA-Δ: Learning Physical State Transition for Vision-Language-Action Models",up:29,href:"https://arxiv.org/abs/2610.21306",abstract:"Vision-language-action (VLA) models transfer semantic knowledge acquired through vision-language pretraining to robot control, achieving strong performance across various benchmarks. However, most VLAs directly map observations to demonstrated actions without explicit supervision of intermediate physical state changes, making them prone to overfitting observation-action correspondences. Some methods introduce intermediate reasoning or future-state prediction in language, visual, or latent spaces to guide action generation, but do not explicitly supervise the physical state transition itself. W",pdfUrl:"https://arxiv.org/pdf/2610.21306",primaryCategory:"cs.CV",published:"2026-10-15T00:00:00Z"},{id:"2610.20731",title:"WorldCast: Exploring Intelligent Visual Generation in World State Prediction",up:28,href:"https://arxiv.org/abs/2610.20731",abstract:"Humans interpret multimodal observations of the world and forecast how it will evolve. Recent multimodal generative systems have demonstrated similar capabilities: they can integrate multimodal context and synthesize visual outputs that depict changes in the world. To characterize this emerging trajectory, we organize model capabilities into a four-level hierarchy and discover that higher-level tasks remain relatively underexplored despite model progress. To bridge this gap, we explore model performance on multi-step world state prediction, a high-level task that requires models to forecast su",pdfUrl:"https://arxiv.org/pdf/2610.20731",primaryCategory:"cs.CV",published:"2026-10-14T00:00:00Z"},{id:"2610.16784",title:"InfoVis: Unified Slide Image Generation and Editing",up:26,href:"https://arxiv.org/abs/2610.16784",abstract:"Generating and editing presentation slides requires models to combine accurate text rendering, instruction following, visual grounding, aesthetic design, and precise editing within one canvas. Existing work covers only subsets of these capabilities and lacks large-scale slide-native supervision and diagnostic evaluation. We formulate four slide-centric tasks and build a scalable data engine with over 13M continual-pretraining records and 1.9M supervised fine-tuning records. We also introduce VisSlideBench, a benchmark of 1,527 manually screened instances that covers all four tasks with task-sp",pdfUrl:"https://arxiv.org/pdf/2610.16784",primaryCategory:"cs.CV",published:"2026-10-12T00:00:00Z"},{id:"2610.22355",title:"OmniVerifier-C1: Decomposed Graded Verifier for Rule-Governed Generative World Modeling",up:26,href:"https://arxiv.org/abs/2610.22355",abstract:"Generative visual verifiers play a crucial role in advancing multimodal intelligence. To enhance the robustness of visual verifiers in complex multimodal scenarios involving compositional requirements, we move beyond conventional binary verifiers that produce only True/False discrete judgments and introduce a verifier that automatically decomposes complex prompts or environmental rules into fine-grained components and assigns pointwise scores to provide a continuous and more informative critique signal. Our experiments further demonstrate that these structured and interpretable outputs improve",pdfUrl:"https://arxiv.org/pdf/2610.22355",primaryCategory:"cs.CL",published:"2026-10-15T00:00:00Z"},{id:"2610.22344",title:"MLExpert: Towards a Generalist Agentic Model for Autonomous Machine Learning Engineering",up:23,href:"https://arxiv.org/abs/2610.22344",abstract:"Large language models (LLMs) are expanding from assisting scientific research and engineering to autonomously developing and improving AI systems, advancing AI for AI (AI4AI) as a pathway toward recursive self-improvement (RSI). Workflow-driven machine learning engineering (MLE) systems provide a practical path toward this pursuit through complex orchestration that manages long-horizon experimentation, while recent MLE systems adopt model-directed interaction, allowing models to autonomously organize experiments and adapt optimization strategies based on execution feedback. However, feedback f",pdfUrl:"https://arxiv.org/pdf/2610.22344",primaryCategory:"cs.AI",published:"2026-10-15T00:00:00Z"},{id:"2610.21656",title:"Data World: Scaling Data Environments from Scratch",up:22,href:"https://arxiv.org/abs/2610.21656",abstract:"Data agents use code to process heterogeneous files and derive analytical insights. Scaling their training faces costly environment curation, privacy and intellectual-property restrictions, and difficulty verifying open-ended findings without known generative truth. Our core insight is to specify the world behind the files before generating the files themselves. We introduce Data World, a multi-agent engine that synthesizes environments, tasks, and rubrics from explicit mechanisms. Independent audits check target recoverability from observed files; rubrics support evaluation and RL rewards. Hu",pdfUrl:"https://arxiv.org/pdf/2610.21656",primaryCategory:"cs.AI",published:"2026-10-15T00:00:00Z"},{id:"2610.20603",title:"CommerceGen-Studio: An End-to-End Framework for Commercial-Grade Main-Image Generation",up:20,href:"https://arxiv.org/abs/2610.20603",abstract:"We present CommerceGen-Studio, an end-to-end framework for generating commercial-grade main images for e-commerce Stock Keeping Units (SKUs). Our framework is organized along a three-stage pipeline of information extraction, semantic rewriting, and multi-condition generation: Prompt-Eval-Refine-Loop Agent (PERL-Agent) distills heterogeneous SKU metadata into concise selling-point text lists through an iterative closed loop of VLM and LLM roles scored by a reference-free rubric. Layout Thinker Optimization (LTO) aligns the rewriter with both caption and rendered-image quality via alternating do",pdfUrl:"https://arxiv.org/pdf/2610.20603",primaryCategory:"cs.CV",published:"2026-10-14T00:00:00Z"},{id:"2610.22282",title:"Routing Policy Optimization for Online Diffusion Reinforcement Learning",up:19,href:"https://arxiv.org/abs/2610.22282",abstract:"Reinforcement learning can align visual generators with reward signals beyond their pretraining objectives, but existing score-function methods typically introduce stochasticity by perturbing the reverse denoising trajectory, leading to costly rollout-based optimization. We instead ask whether stochastic exploration can be introduced inside the generator while preserving its original sampler. Routing Policy Optimization (RPO) answers this question by turning attention routing into a stochastic exploration action. At a few selected denoising levels, each query block keeps its own block and samp",pdfUrl:"https://arxiv.org/pdf/2610.22282",primaryCategory:"cs.CV",published:"2026-10-15T00:00:00Z"},{id:"2610.21439",title:"Each Reward to Its Relevant Tokens: Reward-Specific Token-Level Credit Assignment for Multi-Reward RL",up:14,href:"https://arxiv.org/abs/2610.21439",abstract:"Language models are increasingly trained against several verifiable rewards at once, such as the correctness and the format of a tool call, or the individual constraints of a complex instruction. Reward-decoupled normalization (GDPO) normalizes each reward separately so that different reward combinations keep distinct advantages, but it still spreads every reward's advantage evenly over the whole response, although each verifier checks only a few positions. We propose MRTPO, which assigns the advantage of each reward to the tokens relevant to it, using the information its verifier checks, with",pdfUrl:"https://arxiv.org/pdf/2610.21439",primaryCategory:"cs.LG",doi:"https://doi.org/10.48550/arxiv.2609.32390",year:2026,openalexId:"https://openalex.org/W7214718246",published:"2026-10-15T07:47:04Z"},{id:"2610.22311",title:"Velox: Spatial Memory Makes World Models Efficient",up:14,href:"https://arxiv.org/abs/2610.22311",abstract:"Video world models turn actions and camera motion into long visual rollouts, making video a natural interface for interactive simulation. Such interaction requires responsive generation, yet coherent rollouts must retain visual memory of what has already been generated. Chunked video diffusion models usually keep this context in growing KV caches, so later chunks become progressively slower. To address this bottleneck, we introduce Velox, a training-free attention router for region-level context selection using frustum slab correspondences from streaming geometry. Velox represents historical b",pdfUrl:"https://arxiv.org/pdf/2610.22311",primaryCategory:"cs.CV",published:"2026-10-15T00:00:00Z"},{id:"2610.19063",title:"WorldMemBench: A Comprehensive Benchmark for Memory of Video World Models",up:10,href:"https://arxiv.org/abs/2610.19063",abstract:"As video models enable longer and more realistic interactive experiences, maintaining a world consistent with its history becomes essential. This requires both preserving previously observed content and ensuring coherent world evolution over time. World memory is a critical capability to evaluate alongside visual fidelity and video duration. We introduce WorldMemBench, a benchmark for systematically evaluating world memory in video world models. Across 260 test cases, it assesses static memory through the retention of human identity and appearance, object appearance and geometry, and environme",pdfUrl:"https://arxiv.org/pdf/2610.19063",primaryCategory:"cs.CV",published:"2026-10-13T00:00:00Z"},{id:"2610.21095",title:"Can World and Action Modeling Benefit Each Other under Unified Causal Training?",up:10,href:"https://arxiv.org/abs/2610.21095",abstract:"World and action modeling are closely related, yet their reciprocal benefits under unified causal training remain unclear. We introduce OneWM, a simple framework for unified causal training that treats actions as both conditions for world prediction and targets for policy learning within a shared video-action architecture. Using this framework, we investigate whether learning forward dynamics conditioned on specified actions improves action learning, and whether learning to generate actions in turn improves action-conditioned world modeling. We use LIBERO, LIBERO-Plus, and RoboCasa365 as embod",pdfUrl:"https://arxiv.org/pdf/2610.21095",primaryCategory:"cs.CV",published:"2026-10-15T00:00:00Z"},{id:"2610.21463",title:"Trajectory-Level Speculation with Semantic Verification for Tool-Using Agents",up:9,href:"https://arxiv.org/abs/2610.21463",abstract:"Large language model agents solve tasks through long sequences of tool calls, and the prevailing design has a single strong model generate every step, although many steps are routine enough for a much smaller model. Existing ways of sharing this work keep the strong model as the generator: routers and collaborative agents decide which model handles each query or step, and speculative methods check a small model's drafts one step at a time, usually against the strong model's own action. We introduce SpecAgent, a collaboration protocol that turns the strong model from the author of each step int",pdfUrl:"https://arxiv.org/pdf/2610.21463",primaryCategory:"cs.CL",published:"2026-10-15T00:00:00Z"},{id:"W7171617880",title:"Machine-Speed Intrusion: A Detection Engineering Analysis of the July 2026 Hugging Face Agent Campaign",up:0,href:"https://doi.org/10.5281/zenodo.21686546",doi:"https://doi.org/10.5281/zenodo.21686546",year:2026,openalexId:"https://openalex.org/W7171617880"},{id:"W7171936549",title:"Could a Capability-Security Architecture Have Contained the July 2026 OpenAI-Hugging Face Agentic Exploit Chain?",up:0,href:"https://doi.org/10.5281/zenodo.21715175",doi:"https://doi.org/10.5281/zenodo.21715175",year:2026,openalexId:"https://openalex.org/W7171936549"},{id:"W7203931864",title:"hf-data-agent: a Hugging Face backed RAG data agent",up:0,href:"https://doi.org/10.5281/zenodo.22043399",doi:"https://doi.org/10.5281/zenodo.22043399",year:2026,openalexId:"https://openalex.org/W7203931864"}]}}]);